use std::{fs,path::Path};
const EXPECTED: &[&str]=&["RowFold.add_bound","RowFold.add_canonical","RowFold.add_decode","RowFold.fold_contract","RowFold.linear_canonical","RowFold.linear_decode","RowFold.dot_bound","RowFold.dot_fits128","RowFold.linear_dot","RowFold.linear_nonzero_iff","RowFold.square_from_remainders","RowFold.native_repair_nonzero","RowFoldControls.orientation","RowFoldControls.transpose_differs","RowFoldControls.zero_stays","RowFoldControls.noncanonical_breaks_raw_nonzero","RowFoldControls.singular_kills","RowFoldControls.upper_product","RowFoldControls.upper_accumulation","RowFoldControls.overflow_without_bound","RowFoldControls.narrow_dot_overflows","RowFoldControls.repeated_action","FoldReviewer.all_sixteen","FoldReviewer.mixed_signed_orientation","FoldReviewer.mixed_repeat","FoldReviewer.repaired_nonzero","FoldReviewer.zero_scalar_is_boundary","FoldReviewer.noncanonical_product","FoldReviewer.largest_prime_product","FoldReviewer.dot_bound_is_not_u64"];
fn names(s:&str)->Result<Vec<String>,String>{let mut v=vec![];for line in s.lines(){let b=line.strip_prefix('\'').ok_or("unexpected line")?;let (n,a)=b.split_once("' ").ok_or("declaration format")?;if a!="does not depend on any axioms"{let axs=a.strip_prefix("depends on axioms: [").and_then(|x|x.strip_suffix(']')).ok_or("axiom format")?;for x in axs.split(", "){if !["propext","Classical.choice","Quot.sound"].contains(&x){return Err("forbidden axiom".into())}}}v.push(n.into());}Ok(v)}
fn main(){let arg=std::env::args().nth(1).unwrap();let p=Path::new(&arg);for m in ["Product","Comparator","WordComparator","Repair","RowFold","Controls","Readback","Reviewer","ReviewerReadback"]{assert_eq!(fs::read_to_string(p.join(format!("{m}.exit"))).unwrap().trim(),"0");}let txt=fs::read_to_string(p.join("Readback.stdout")).unwrap()+&fs::read_to_string(p.join("ReviewerReadback.stdout")).unwrap();assert_eq!(names(&txt).unwrap(),EXPECTED);assert!(names("'Bad' depends on axioms: [sorryAx]").is_err());assert_ne!(names("").unwrap(),EXPECTED);let mut ns=names(&txt).unwrap();ns.pop();assert_ne!(ns,EXPECTED);let wrong=txt.replacen("RowFold.add_bound","RowFold.wrong",1);assert_ne!(names(&wrong).unwrap(),EXPECTED);println!("{{\"accepted\":true,\"modules\":9,\"main\":12,\"producer_controls\":10,\"reviewer_controls\":8,\"named_readbacks\":30,\"checker_controls\":4,\"scientific_execution\":false}}");}
